type Note = { text: String }

service jobs from cron {
    limits { maxBody: 1_000_000 }   // ✗ a schedule takes no request body
    on schedule("0 0 * * *") () -> Effect[Result[(), String]] { … }
}

service api from http {
    limits { maxBody: 1_000_000 }   // ✓
    on POST("/notes") (body: Note) -> Effect[HttpResult[String]] by v: Visitor { … }
}
